CREATE TABLE app_users (id UUID PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(160) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'USER', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE accounts (id UUID PRIMARY KEY, owner_id UUID NOT NULL REFERENCES app_users(id), account_number VARCHAR(24) NOT NULL UNIQUE, currency CHAR(3) NOT NULL DEFAULT 'PEN', balance NUMERIC(19,2) NOT NULL DEFAULT 0 CHECK (balance >= 0), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_accounts_owner ON accounts(owner_id);
CREATE TABLE transfers (id UUID PRIMARY KEY, sender_id UUID NOT NULL REFERENCES accounts(id), recipient_id UUID NOT NULL REFERENCES accounts(id), amount NUMERIC(19,2) NOT NULL CHECK (amount > 0), status VARCHAR(20) NOT NULL, reference VARCHAR(200), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (sender_id <> recipient_id));
CREATE INDEX ix_transfers_sender ON transfers(sender_id, created_at DESC);
CREATE INDEX ix_transfers_recipient ON transfers(recipient_id, created_at DESC);
CREATE TABLE ledger_entries (id UUID PRIMARY KEY, transfer_id UUID NOT NULL REFERENCES transfers(id), account_id UUID NOT NULL REFERENCES accounts(id), direction VARCHAR(10) NOT NULL CHECK(direction IN ('DEBIT','CREDIT')), amount NUMERIC(19,2) NOT NULL CHECK(amount > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(transfer_id, account_id, direction));
CREATE TABLE idempotency_keys (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_users(id), request_key VARCHAR(100) NOT NULL, request_hash VARCHAR(64) NOT NULL, transfer_id UUID NOT NULL REFERENCES transfers(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, request_key));
